(function(root,factory){const api=factory();if(typeof module==='object'&&module.exports)module.exports=api;else root.TabGroupsModel=api})(typeof globalThis!=='undefined'?globalThis:this,function(){'use strict';const KEY='ob.tabGroups.v1',COLORS=['blue','pink','mint','amber','violet','silver'];function fail(c){throw Object.assign(new Error(c),{code:c})}function id(v){if(typeof v!=='string'||!/^[a-zA-Z0-9_-]{1,64}$/.test(v))fail('INVALID_ID');return v}function text(v,max){if(typeof v!=='string'||!v.trim()||v.length>max)fail('INVALID_TEXT');return v.trim()}function url(v){if(v==='about:newtab')return v;if(typeof v!=='string'||v.length>2048||/[\x00-\x20\x7f]/.test(v))fail('INVALID_URL');let u;try{u=new URL(v)}catch(_){fail('INVALID_URL')}if(!['http:','https:'].includes(u.protocol)||u.username||u.password)fail('INVALID_URL');return u.href}function group(g){if(!g||!COLORS.includes(g.color))fail('INVALID_GROUP');return{id:id(g.id),name:text(g.name,32),color:g.color}}
function thumbnail(v){if(v==null)return null;if(typeof v!=='string'||v.length>200000)fail('INVALID_THUMBNAIL');if(v==='thumbnail.svg'||/^media\/[a-zA-Z0-9_-]{1,80}\.(webp|png|jpg)$/.test(v)||/^data:image\/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$/.test(v))return v;fail('INVALID_THUMBNAIL')}function validate(s){if(!s||s.version!==1||!Number.isSafeInteger(s.revision)||s.revision<0||!Array.isArray(s.groups)||s.groups.length>12||!Array.isArray(s.tabs)||s.tabs.length>64)fail('INVALID_STATE');const groups=s.groups.map(group),ids=new Set(groups.map(g=>g.id));if(ids.size!==groups.length)fail('DUPLICATE_ID');const tabs=s.tabs.map(t=>{if(!t||typeof t.pinned!=='boolean'||typeof t.private!=='boolean')fail('INVALID_TAB');if(t.groupId!==null&&!ids.has(t.groupId))fail('MISSING_GROUP');return{id:id(t.id),title:text(t.title,160),url:url(t.url),groupId:t.groupId,pinned:t.pinned,private:t.private,thumbnail:t.private?null:thumbnail(t.thumbnail)}});if(new Set(tabs.map(t=>t.id)).size!==tabs.length)fail('DUPLICATE_ID');if(tabs.filter(t=>t.pinned).length>16)fail('PIN_LIMIT');return{version:1,revision:s.revision,groups,tabs}}
function apply(state,op,expected){const s=validate(state);if(expected!==s.revision)fail('STALE_STATE');let g,t;if(!op||typeof op.type!=='string')fail('INVALID_OPERATION');switch(op.type){case'tab.create':s.tabs.push({id:id(op.id),title:'New tab',url:'about:newtab',groupId:null,pinned:false,private:false,thumbnail:null});break;case'tab.close':if(!s.tabs.some(x=>x.id===op.id))fail('MISSING_TAB');s.tabs=s.tabs.filter(x=>x.id!==op.id);break;case'tab.move':{const from=s.tabs.findIndex(x=>x.id===op.id);if(from<0)fail('MISSING_TAB');if(![-1,1].includes(op.delta))fail('INVALID_OPERATION');const to=Math.max(0,Math.min(s.tabs.length-1,from+op.delta));const [tab]=s.tabs.splice(from,1);s.tabs.splice(to,0,tab);break;}case'group.create':g=group(op.group);if(s.groups.some(x=>x.id===g.id))fail('DUPLICATE_ID');s.groups.push(g);break;case'group.update':g=group(op.group);if(!s.groups.some(x=>x.id===g.id))fail('MISSING_GROUP');s.groups=s.groups.map(x=>x.id===g.id?g:x);break;case'group.delete':id(op.id);if(!s.groups.some(x=>x.id===op.id))fail('MISSING_GROUP');s.groups=s.groups.filter(x=>x.id!==op.id);s.tabs=s.tabs.map(x=>x.groupId===op.id?{...x,groupId:null}:x);break;case'tab.pin':case'tab.group':t=s.tabs.find(t=>t.id===op.id);if(!t)fail('MISSING_TAB');if(op.type==='tab.pin'){if(typeof op.pinned!=='boolean')fail('INVALID_PIN');t.pinned=op.pinned}else{if(op.groupId!==null&&!s.groups.some(g=>g.id===op.groupId))fail('MISSING_GROUP');t.groupId=op.groupId}break;default:fail('INVALID_OPERATION')}s.revision++;return validate(s)}
function persist(storage,state){const s=validate(state),publicState={...s,tabs:s.tabs.filter(t=>!t.private)};try{storage.setItem(KEY,JSON.stringify(publicState))}catch(_){fail('STORAGE_FULL')}return s}function load(storage){try{const raw=storage.getItem(KEY);return raw===null?null:validate(JSON.parse(raw))}catch(e){fail(e.code||'INVALID_STORE')}}function visible(state,filter){const s=validate(state);return s.tabs.filter(t=>filter==='all'||filter==='pinned'&&t.pinned||filter==='ungrouped'&&t.groupId===null||t.groupId===filter).sort((a,b)=>Number(b.pinned)-Number(a.pinned))}return Object.freeze({KEY,COLORS,validate,apply,persist,load,visible});});
